def _slot_freshness_slo_seconds(slot: dict[str, Any]) -> int:
    raw = slot.get("freshness_slo_seconds")
    if raw not in {None, ""}:
        return max(_safe_int(raw, 300), 30)
    role = str(slot.get("bot_role") or "")
    kind = str(slot.get("slot_kind") or "")
    sleeve_profile = str(slot.get("sleeve_profile") or "")
    if "aggressive_intraday" in kind:
        return 60
    if _is_quant_model_kind(kind) or sleeve_profile in QUANT_MODEL_SLEEVE_PROFILES:
        return 300
    if _is_exotic_derivative_kind(kind):
        return 300
    if role == "options_sub_bot" or "options" in kind:
        return 180
    if "macro" in kind or "event" in kind:
        return 300
    return 900


def _slot_retention_profile(slot: dict[str, Any]) -> str:
    raw = str(slot.get("retention_profile") or "").strip()
    if raw:
        return raw
    kind = str(slot.get("slot_kind") or "")
    role = str(slot.get("bot_role") or "")
    sleeve_profile = str(slot.get("sleeve_profile") or "")
    if "aggressive_intraday" in kind:
        return "hot_intraday_7d_warm_90d"
    if _is_quant_model_kind(kind) or sleeve_profile in QUANT_MODEL_SLEEVE_PROFILES:
        return "hot_quant_research_14d_warm_365d"
    if _is_exotic_derivative_kind(kind):
        return "hot_exotic_derivatives_14d_warm_365d"
    if role == "options_sub_bot" or "options" in kind:
        return "hot_options_14d_warm_180d"
    return "standard_candidate_30d_warm_180d"


def _slot_training_thresholds(slot: dict[str, Any]) -> tuple[int, int]:
    kind = str(slot.get("slot_kind") or "")
    role = str(slot.get("bot_role") or "")
    sleeve_profile = str(slot.get("sleeve_profile") or "")
    if "aggressive_intraday" in kind:
        return 5000, 5
    if _is_quant_model_kind(kind) or sleeve_profile in QUANT_MODEL_SLEEVE_PROFILES:
        return 3000, 14
    if _is_exotic_derivative_kind(kind):
        return 2500, 14
    if role == "options_sub_bot" or "options" in kind:
        return 1500, 7
    return 1000, 7


def _slot_provider_capability_fields(slot: dict[str, Any]) -> dict[str, Any]:
    kind = str(slot.get("slot_kind") or "")
    sleeve_profile = str(slot.get("sleeve_profile") or "")
    if _is_quant_model_kind(kind) or sleeve_profile in QUANT_MODEL_SLEEVE_PROFILES:
        return {
            "provider_capability_profile": "research_only_quant_proxy",
            "direct_market_data_available": False,
            "direct_execution_allowed": False,
            "proxy_data_sources": [
                "listed_option_surface",
                "market_context_features",
                "external_context_quant_model_control",
                "runtime_decision_history",
            ],
            "schwab_direct_inputs": ["listed_equity_etf_quotes", "listed_option_chains"],
            "proxy_only_reason": "Quant model bots are research/data-collection only; they enrich features and labels but cannot route orders.",
        }
    exotic_capabilities = provider_capabilities_for_sleeve(sleeve_profile)
    if exotic_capabilities:
        return {
            "provider_capability_profile": str(exotic_capabilities.get("proxy_mode", "") or ""),
            "direct_market_data_available": bool(exotic_capabilities.get("direct_product_market_data", False)),
            "direct_execution_allowed": bool(exotic_capabilities.get("direct_execution_allowed", False)),
            "proxy_data_sources": list(exotic_capabilities.get("public_inputs") or []),
            "schwab_direct_inputs": list(exotic_capabilities.get("schwab_direct_inputs") or []),
            "proxy_only_reason": str(exotic_capabilities.get("notes", "") or ""),
        }
    return {
        "provider_capability_profile": "",
        "direct_market_data_available": None,
        "direct_execution_allowed": None,
        "proxy_data_sources": [],
        "schwab_direct_inputs": [],
        "proxy_only_reason": "",
    }


def _slot_label_metadata(slot: dict[str, Any], *, min_observations: int) -> dict[str, Any]:
    kind = str(slot.get("slot_kind") or "")
    sleeve_profile = str(slot.get("sleeve_profile") or "")
    is_quant_model = _is_quant_model_kind(kind) or sleeve_profile in QUANT_MODEL_SLEEVE_PROFILES
    label_contract = slot.get("label_contract") if isinstance(slot.get("label_contract"), dict) else {}
    if not label_contract and is_quant_model:
        label_contract = _quant_label_contract(kind, sleeve_profile)
    contract_version = str(label_contract.get("contract_version") or "").strip()
    if not contract_version:
        if is_quant_model:
            contract_version = "quant_research_labels_v1"
        elif _is_exotic_derivative_kind(kind):
            contract_version = "advanced_derivatives_proxy_labels_v1"
    tags = ordered_unique(
        [
            "research_only",
            "collection_only",
            "proxy_derived" if is_quant_model or _is_exotic_derivative_kind(kind) else "",
            "execution_blocked",
            f"sleeve_family:{str(slot.get('sleeve_family') or 'unassigned')}",
            f"sleeve_profile:{sleeve_profile or 'unassigned'}",
            f"data_floor:{min_observations}",
        ]
    )
    return {
        "label_contract": label_contract,
        "data_label_contract_version": contract_version,
        "labeling_tags": tags,
        "execution_policy_label": "research_only_no_execution" if (is_quant_model or _is_exotic_derivative_kind(kind)) else "collection_only_no_execution",
        "eligible_for_master_vote": False,
    }


def _slot_registry_row(slot: dict[str, Any]) -> dict[str, Any]:
    min_observations, min_days = _slot_training_thresholds(slot)
    sleeve_profile = str(slot.get("sleeve_profile") or "")
    provider_fields = _slot_provider_capability_fields(slot)
    label_metadata = _slot_label_metadata(slot, min_observations=min_observations)
    return {
        "bot_id": str(slot.get("bot_id") or ""),
        "bot_role": str(slot.get("bot_role") or "unknown"),
        "active": True,
        "reason": "planned_roster_expansion_slot",
        "weight": 0.0,
        "preference_score": 0.0,
        "quality_score": 0.0,
        "test_accuracy": None,
        "candidate_test_accuracy": None,
        "candidate_quality_score": 0.0,
        "previous_best_accuracy": None,
        "no_improvement_streak": 0,
        "deleted_from_rotation": False,
        "delete_reason": "",
        "promoted": False,
        "promotion_reason": "planned_roster_expansion_slot",
        "model_path": "",
        "log_file": "",
        "candidate_log_file": "",
        "lifecycle_state": "data_collection_only",
        "data_collection_active": True,
        "data_collection_started_utc": iso_now(),
        "data_collection_observations": 0,
        "data_collection_mode": "active_observer",
        "data_collection_reason": "active_observer_until_minimum_samples",
        "trading_enabled": False,
        "paper_trading_enabled": False,
        "live_trading_enabled": False,
        "allocation_enabled": False,
        "execution_enabled": False,
        "rotation_blocked": True,
        "rotation_block_reason": "data_collection_only_zero_weight",
        "training_excluded": True,
        "exclude_from_training": True,
        "training_candidate_after_threshold": True,
        "training_exclusion_reason": "collecting_observations_before_training",
        "training_exclusion_until": "minimum_data_collection_threshold_met",
        "training_threshold_policy": "eligible_when_minimum_observations_and_days_met",
        "minimum_training_observations": min_observations,
        "minimum_data_collection_days": min_days,
        "promotion_blocked_until": "minimum_data_collection_threshold_met",
        "promotion_block_reason": "data_collection_only_no_training_yet",
        "slot_label": str(slot.get("slot_label") or ""),
        "slot_kind": str(slot.get("slot_kind") or ""),
        "sleeve_profile": sleeve_profile,
        "sleeve_family": str(slot.get("sleeve_family") or ""),
        "slot_priority": str(slot.get("priority") or "medium"),
        "slot_objective": str(slot.get("objective") or ""),
        "target_functions": list(slot.get("target_functions") or []),
        "preferred_regimes": list(slot.get("preferred_regimes") or []),
        "bootstrap_teacher_bot_ids": list(slot.get("bootstrap_teacher_bot_ids") or []),
        "correlation_peer_sleeves": list(slot.get("correlation_peer_sleeves") or []),
        "correlation_dependencies": list(slot.get("correlation_dependencies") or []),
        "data_intake_collections": _slot_data_intake_collections(slot),
        "storage_targets": _slot_storage_targets(slot),
        "freshness_slo_seconds": _slot_freshness_slo_seconds(slot),
        "retention_profile": _slot_retention_profile(slot),
        **provider_fields,
        **label_metadata,
    }


def _refresh_registry_summary(payload: dict[str, Any]) -> None:
    rows = _registry_rows(payload)
    summary = payload.get("summary") if isinstance(payload.get("summary"), dict) else {}
    active_rows = [row for row in rows if bool(row.get("active", False))]
    data_collection_rows = [row for row in rows if str(row.get("lifecycle_state") or "").strip().lower() == "data_collection_only"]
    summary["total_bots"] = len(rows)
    summary["active_bots"] = len(active_rows)
    summary["inactive_bots"] = max(len(rows) - len(active_rows), 0)
    summary["active_signal_sub_bots"] = sum(1 for row in rows if bool(row.get("active", False)) and str(row.get("bot_role") or "") == "signal_sub_bot")
    summary["active_infrastructure_sub_bots"] = sum(1 for row in rows if bool(row.get("active", False)) and str(row.get("bot_role") or "") == "infrastructure_sub_bot")
    summary["active_options_sub_bots"] = sum(1 for row in rows if bool(row.get("active", False)) and str(row.get("bot_role") or "") == "options_sub_bot")
    summary["active_futures_sub_bots"] = sum(1 for row in rows if bool(row.get("active", False)) and str(row.get("bot_role") or "") == "futures_sub_bot")
    summary["active_quant_model_bots"] = sum(1 for row in rows if bool(row.get("active", False)) and str(row.get("sleeve_family") or "") == "quant_models")
    summary["inactive_signal_sub_bots"] = sum(1 for row in rows if not bool(row.get("active", False)) and str(row.get("bot_role") or "") == "signal_sub_bot")
    summary["inactive_infrastructure_sub_bots"] = sum(1 for row in rows if not bool(row.get("active", False)) and str(row.get("bot_role") or "") == "infrastructure_sub_bot")
    summary["inactive_options_sub_bots"] = sum(1 for row in rows if not bool(row.get("active", False)) and str(row.get("bot_role") or "") == "options_sub_bot")
    summary["inactive_futures_sub_bots"] = sum(1 for row in rows if not bool(row.get("active", False)) and str(row.get("bot_role") or "") == "futures_sub_bot")
    summary["data_collection_only_bots"] = len(data_collection_rows)
    summary["training_excluded_bots"] = sum(1 for row in rows if bool(row.get("training_excluded", False)) or bool(row.get("exclude_from_training", False)))
    summary["data_collection_training_ready_bots"] = sum(1 for row in data_collection_rows if bool(row.get("data_collection_training_ready", False)))
    payload["summary"] = summary
    payload["updated_at_utc"] = iso_now()


def build_payload(project_root: Path = PROJECT_ROOT) -> dict[str, Any]:
    registry = load_json(project_root / "master_bot_registry.json")
    teacher_quality = load_json(project_root / "governance" / "distillation" / "teacher_quality_latest.json")
    supportability = load_json(project_root / "governance" / "health" / "supportability_control_latest.json")
    coverage_seed = load_json(project_root / "governance" / "walk_forward" / "coverage_seed_latest.json")
    regime_control = load_json(project_root / "governance" / "health" / "regime_control_plane_latest.json")

    registry_map = _registry_row_map(_registry_rows(registry))
    teacher_by_role, teacher_overall = _teacher_index(teacher_quality)
    gap_by_role = _gap_by_role(supportability)
    seed_by_role = _seed_queue_by_role(coverage_seed)
    live_regime = str(regime_control.get("regime_state") or "").strip() or "unknown"

    role_counts: dict[str, int] = {}
    priority_counts: dict[str, int] = {}
    teacher_anchor_missing_roles: set[str] = set()
    slots: list[dict[str, Any]] = []
    critical_slots_missing: list[str] = []
    regime_priority_slots: list[dict[str, Any]] = []
    registered_count = 0
    teacher_anchor_ready_count = 0

    for spec in sorted(
        DEFAULT_SLOT_SPECS,
        key=lambda row: (
            -_regime_fit_score(list(row.get("preferred_regimes") or []), live_regime),
            _priority_value(str(row.get("priority") or "")),
            str(row.get("bot_id") or ""),
        ),
    ):
        bot_id = str(spec.get("bot_id") or "").strip().lower()
        role = str(spec.get("bot_role") or "unknown").strip() or "unknown"
        role_counts[role] = int(role_counts.get(role, 0) + 1)
        priority = str(spec.get("priority") or "medium").strip().lower() or "medium"
        priority_counts[priority] = int(priority_counts.get(priority, 0) + 1)
        row = registry_map.get(bot_id, {})
        registered = bool(row)
        if registered:
            registered_count += 1
        same_role_teachers = list(teacher_by_role.get(role) or [])
        bootstrap_teachers = same_role_teachers[:3] if same_role_teachers else list((spec.get("bootstrap_teacher_bot_ids") or teacher_overall[:3])[:3])
        teacher_anchor_ready = bool(same_role_teachers)
        if teacher_anchor_ready:
            teacher_anchor_ready_count += 1
        else:
            teacher_anchor_missing_roles.add(role)
        if priority == "critical" and not registered:
            critical_slots_missing.append(bot_id)
        regime_fit_score = _regime_fit_score(list(spec.get("preferred_regimes") or []), live_regime)
        slot_row = {
            **spec,
            "registered": registered,
            "registry_reason": str(row.get("reason") or "") if registered else "",
            "registry_promotion_reason": str(row.get("promotion_reason") or "") if registered else "",
            "same_role_teacher_bot_ids": same_role_teachers[:3],
            "bootstrap_teacher_bot_ids": bootstrap_teachers,
            "teacher_anchor_ready": teacher_anchor_ready,
            "current_teacher_gap": int(gap_by_role.get(role, 0)),
            "current_seed_queue_count": int(seed_by_role.get(role, 0)),
            "current_live_regime": live_regime,
            "regime_fit": regime_fit_score > 0,
            "regime_fit_score": regime_fit_score,
            "data_intake_collections": _slot_data_intake_collections(spec),
            "storage_targets": _slot_storage_targets(spec),
            "freshness_slo_seconds": _slot_freshness_slo_seconds(spec),
            "retention_profile": _slot_retention_profile(spec),
        }
        slots.append(slot_row)
        if regime_fit_score > 0:
            regime_priority_slots.append(
                {
                    "bot_id": bot_id,
                    "bot_role": role,
                    "slot_label": str(spec.get("slot_label") or ""),
                    "priority": priority,
                    "registered": registered,
                    "regime_fit_score": regime_fit_score,
                    "preferred_regimes": list(spec.get("preferred_regimes") or []),
                    "rationale": str(spec.get("rationale") or ""),
                }
            )

    planned_slot_count = len(DEFAULT_SLOT_SPECS)
    missing_slot_count = max(planned_slot_count - registered_count, 0)
    overall_status = "ready" if missing_slot_count <= 0 else "degraded"

    recommended_actions = ordered_unique(
        [
            "sync the planned roster expansion slots into the master registry so the bench roadmap is explicit" if missing_slot_count > 0 else "",
            "train the critical infrastructure teacher slot first so infrastructure students stop relying on cross-role mentors",
            "upgrade the signal fallback champion and defensive options teacher before adding more student-only bots",
            "seed walk-forward coverage for the new signal and infrastructure slots as soon as runtime inputs are healthy",
            "treat the slippage, runtime-input, and drawdown allocator slots as infrastructure prerequisites for multi-week uptime",
            f"prioritize the current {live_regime} buildout around "
            + ", ".join(str(row.get("bot_id") or "") for row in regime_priority_slots[:3])
            if regime_priority_slots
            else "",
        ]
    )

    return {
        "timestamp_utc": iso_now(),
        "schema_version": 1,
        "ok": missing_slot_count <= 0,
        "overall_status": overall_status,
        "summary": {
            "planned_slot_count": planned_slot_count,
            "registered_slot_count": registered_count,
            "missing_slot_count": missing_slot_count,
            "critical_slot_count": int(priority_counts.get("critical", 0)),
            "critical_slots_missing": critical_slots_missing,
            "teacher_anchor_ready_count": teacher_anchor_ready_count,
            "teacher_anchor_missing_roles": sorted(teacher_anchor_missing_roles),
            "role_counts": role_counts,
            "priority_counts": priority_counts,
            "live_regime": live_regime,
            "regime_fit_slot_count": len(regime_priority_slots),
        },
        "teacher_anchor_pool": {
            "overall": teacher_overall[:6],
            "by_role": {role: ids[:3] for role, ids in teacher_by_role.items()},
        },
        "roster_slots": slots,
        "current_regime_priority_slots": regime_priority_slots[:5],
        "infra_bots": [
            "roster_expansion_slots",
            "roster_resilience_planner",
            "teacher_quality_guard",
            "bot_quality_autopilot",
            "walk_forward_coverage_seed",
        ],
        "recommended_actions": recommended_actions,
        "registry_sync": {
            "applied": False,
            "added_slots": 0,
            "backup_path": "",
        },
    }


def apply_registry(project_root: Path = PROJECT_ROOT, *, registry_path: Path = DEFAULT_REGISTRY_PATH) -> dict[str, Any]:
    registry = load_json(registry_path)
    rows = _registry_rows(registry)
    row_map = _registry_row_map(rows)
    missing_slots = [spec for spec in DEFAULT_SLOT_SPECS if str(spec.get("bot_id") or "").strip().lower() not in row_map]
    refreshed_slots: list[str] = []
    for spec in DEFAULT_SLOT_SPECS:
        bot_id = str(spec.get("bot_id") or "").strip().lower()
        row = row_map.get(bot_id)
        if not isinstance(row, dict):
            continue
        min_observations, min_days = _slot_training_thresholds(spec)
        base_freshness_slo = _slot_freshness_slo_seconds(spec)
        compute_guard_mode = str(row.get("data_collection_compute_guard_mode") or "").strip().lower()
        if compute_guard_mode in {"soft_cap", "sustain", "protect_live"}:
            base_freshness_slo = max(base_freshness_slo, _safe_int(row.get("freshness_slo_seconds"), base_freshness_slo))
        updates = {
            "slot_label": str(spec.get("slot_label") or ""),
            "slot_kind": str(spec.get("slot_kind") or ""),
            "sleeve_profile": str(spec.get("sleeve_profile") or ""),
            "sleeve_family": str(spec.get("sleeve_family") or ""),
            "slot_priority": str(spec.get("priority") or "medium"),
            "slot_objective": str(spec.get("objective") or ""),
            "target_functions": list(spec.get("target_functions") or []),
            "preferred_regimes": list(spec.get("preferred_regimes") or []),
            "bootstrap_teacher_bot_ids": list(spec.get("bootstrap_teacher_bot_ids") or []),
            "correlation_peer_sleeves": list(spec.get("correlation_peer_sleeves") or []),
            "correlation_dependencies": list(spec.get("correlation_dependencies") or []),
            "data_intake_collections": _slot_data_intake_collections(spec),
            "storage_targets": _slot_storage_targets(spec),
            "freshness_slo_seconds": base_freshness_slo,
            "retention_profile": _slot_retention_profile(spec),
        }
        updates.update(_slot_provider_capability_fields(spec))
        updates.update(_slot_label_metadata(spec, min_observations=min_observations))
        graduated_from_collection = (
            str(row.get("lifecycle_state") or "").strip().lower()
            not in {"", "inactive", "data_collection_only"}
            or bool(row.get("promoted", False))
            or str(row.get("promotion_reason") or "").strip().lower()
            not in {"", "planned_roster_expansion_slot", "new_runtime_candidate"}
        )
        if not graduated_from_collection:
            updates.update(
                {
                    "active": True,
                    "lifecycle_state": "data_collection_only",
                    "data_collection_active": True,
                    "data_collection_started_utc": str(row.get("data_collection_started_utc") or iso_now()),
                    "data_collection_observations": _safe_int(row.get("data_collection_observations"), 0),
                    "data_collection_mode": "active_observer",
                    "data_collection_reason": "active_observer_until_minimum_samples",
                    "trading_enabled": False,
                    "paper_trading_enabled": False,
                    "live_trading_enabled": False,
                    "allocation_enabled": False,
                    "execution_enabled": False,
                    "weight": 0.0,
                    "preference_score": 0.0,
                    "rotation_blocked": True,
                    "rotation_block_reason": "data_collection_only_zero_weight",
                    "training_excluded": True,
                    "exclude_from_training": True,
                    "training_candidate_after_threshold": True,
                    "training_exclusion_reason": "collecting_observations_before_training",
                    "training_exclusion_until": "minimum_data_collection_threshold_met",
                    "training_threshold_policy": "eligible_when_minimum_observations_and_days_met",
                    "minimum_training_observations": min_observations,
                    "minimum_data_collection_days": min_days,
                    "promotion_blocked_until": "minimum_data_collection_threshold_met",
                    "promotion_block_reason": "data_collection_only_no_training_yet",
                }
            )
        changed = False
        for key, value in updates.items():
            if row.get(key) != value:
                row[key] = value
                changed = True
        if changed:
            refreshed_slots.append(str(spec.get("bot_id") or ""))
    backup_path = ""
    if missing_slots or refreshed_slots:
        lifecycle_dir = project_root / "governance" / "lifecycle"
        lifecycle_dir.mkdir(parents=True, exist_ok=True)
        stamp = iso_now().replace(":", "").replace("+00:00", "Z")
        backup = lifecycle_dir / f"master_bot_registry.roster_expansion_backup_{stamp}.json"
        if registry_path.exists():
            backup.write_text(registry_path.read_text(encoding="utf-8"), encoding="utf-8")
            backup_path = str(backup)
    if missing_slots:
        rows.extend(_slot_registry_row(spec) for spec in missing_slots)
        registry["sub_bots"] = rows
    if missing_slots or refreshed_slots:
        _refresh_registry_summary(registry)
        registry_path.write_text(json.dumps(registry, ensure_ascii=True, indent=2), encoding="utf-8")
    return {
        "applied": bool(missing_slots or refreshed_slots),
        "added_slots": len(missing_slots),
        "added_bot_ids": [str(spec.get("bot_id") or "") for spec in missing_slots],
        "refreshed_slots": len(refreshed_slots),
        "refreshed_bot_ids": refreshed_slots,
        "backup_path": backup_path,
        "registry_path": str(registry_path),
    }


def main() -> int:
    parser = argparse.ArgumentParser(description="Track and register the planned roster expansion slots for teacher coverage, fallback champions, and infrastructure guards.")
    parser.add_argument("--project-root", default=str(PROJECT_ROOT))
    parser.add_argument("--registry", default=str(DEFAULT_REGISTRY_PATH))
    parser.add_argument("--out-file", default=str(DEFAULT_OUT_PATH))
    parser.add_argument("--apply-registry", action="store_true")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args()

    project_root = Path(args.project_root).resolve()
    out_path = Path(args.out_file).expanduser()
    registry_path = Path(args.registry).expanduser()

    apply_result = {
        "applied": False,
        "added_slots": 0,
        "backup_path": "",
        "added_bot_ids": [],
        "refreshed_slots": 0,
        "refreshed_bot_ids": [],
        "registry_path": str(registry_path),
    }
    if args.apply_registry:
        apply_result = apply_registry(project_root, registry_path=registry_path)

    payload = build_payload(project_root)
    payload["registry_sync"] = apply_result
    write_payload(out_path, payload)
    if args.json:
        print(json.dumps(payload, ensure_ascii=True))
    else:
        print(
            "roster_expansion_slots "
            f"overall_status={payload.get('overall_status', '')} "
            f"registered_slots={int(((payload.get('summary') or {}).get('registered_slot_count', 0) or 0))} "
            f"missing_slots={int(((payload.get('summary') or {}).get('missing_slot_count', 0) or 0))}"
        )
    return 0 if payload.get("overall_status") == "ready" else 2


if __name__ == "__main__":
    raise SystemExit(main())
